    func testInlineEditRejectsNumbersBeyondSupportedRange() throws {
        let canvas = EditorCanvasView(image: TestSupport.solidImage(width: 100, height: 80))
        canvas.setTool(.marker)
        try click(canvas, at: NSPoint(x: 40, y: 40))

        for invalid in ["1000000", "9223372036854775807", "-4"] {
            canvas.mouseDown(with: try mouseEvent(type: .leftMouseDown, canvas: canvas,
                                                  location: NSPoint(x: 40, y: 40), clickCount: 2))
            let editor = try XCTUnwrap(canvas.subviews.compactMap { $0 as? NSTextView }.first)
            editor.string = invalid
            editor.keyDown(with: try keyEvent(keyCode: 36, characters: "\r"))
            XCTAssertEqual(markerNumbers(canvas), [1], "\(invalid) must not be accepted")
        }

        // The largest supported value is accepted and stops further placement.
        canvas.mouseDown(with: try mouseEvent(type: .leftMouseDown, canvas: canvas,
                                              location: NSPoint(x: 40, y: 40), clickCount: 2))
        let editor = try XCTUnwrap(canvas.subviews.compactMap { $0 as? NSTextView }.first)
        editor.string = "999999"
        editor.keyDown(with: try keyEvent(keyCode: 36, characters: "\r"))
        XCTAssertEqual(markerNumbers(canvas), [999999])
        try click(canvas, at: NSPoint(x: 90, y: 70))
        XCTAssertEqual(markerNumbers(canvas), [999999], "Range exhausted: no wrap to a duplicate")
    }

    func testMarkerRendersFillAndContrastingContent() throws {
        let canvas = EditorCanvasView(image: TestSupport.solidImage(width: 120, height: 100, color: .systemBlue))
        canvas.setColor(.systemRed)
        canvas.setTool(.marker)
        try click(canvas, at: NSPoint(x: 60, y: 50))

        let composite = canvas.compositeImage()
        let rep = try XCTUnwrap(composite.representations.compactMap { $0 as? NSBitmapImageRep }.first)

        // Marker center in canvas (60,50) maps into the export crop, which
        // starts at the base image origin (canvasEdgeInset = 24).
        let centerX = 60 - 24
        let centerY = 50 - 24
        var foundFill = false
        var foundContrast = false
        for dy in -10...10 {
            for dx in -10...10 {
                guard let pixel = rep.colorAt(x: centerX + dx, y: centerY + dy)?.usingColorSpace(.deviceRGB) else { continue }
                if pixel.redComponent > 0.8 && pixel.greenComponent < 0.4 && pixel.blueComponent < 0.4 {
                    foundFill = true
                }
                if pixel.redComponent > 0.8 && pixel.greenComponent > 0.8 && pixel.blueComponent > 0.8 {
                    foundContrast = true
                }
            }
        }
        XCTAssertTrue(foundFill, "Marker fill should render in the annotation color")
        XCTAssertTrue(foundContrast, "Marker numeral should render in a contrasting color")

        // Far outside the marker, the base image is untouched.
        let corner = try XCTUnwrap(rep.colorAt(x: 2, y: 2)?.usingColorSpace(.deviceRGB))
        XCTAssertGreaterThan(corner.blueComponent, 0.5)
        XCTAssertLessThan(corner.redComponent, 0.4)
    }
